OC.Log={levels:["Debug","Info","Warning","Error","Fatal"],addEntries:function(e){for(var t=0;t<e.length;t++){var a=e[t],o=$("<tr/>"),d=$("<td/>");d.text(OC.Log.levels[a.level]),o.append(d);var n=$("<td/>");n.text(a.app),o.append(n);var l=$("<td/>");l.addClass("log-message"),l.text(a.message),o.append(l);var s=$("<td/>");s.addClass("date"),isNaN(a.time)?s.text(a.time):s.text(formatDate(1e3*a.time)),o.append(s),$("#log").append(o)}OC.Log.loaded+=e.length}},$(document).ready(function(){$("#moreLog").click(function(){OC.Log.getMore()}),$("#lessLog").click(function(){OC.Log.showLess()})});